quests[61868] = { id = 61868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbequem Undercover", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61869] = { id = 61869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchen und finden", description = "Zerekriss gehört uns... mit allem, was sich darin befindet.\n\nDer Primus war persönlich an der Gestaltung dieser Nekropole beteiligt. Es war wirklich ein unvergesslicher Anblick, wie seine Hände dieses Gefäß formten.\n\nEs wäre klug, den Raum zu durchsuchen. Vielleicht können einige Werkzeuge, die er dort aufbewahrt hat, uns von Nutzen sein.", sourceObjective = "Durchsucht die Truhe des Vorarbeiters nach wertvollen Gegenständen.", progress = "Was habt Ihr gefunden?", completion = "Die haben dem Primus gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[61870] = { id = 61870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlgeschlagenes Experiment", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61871] = { id = 61871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktuelle Anliegen", description = "Ihr habt Euch hier gut geschlagen. MUTTER und ich überlegen uns, was als Nächstes zu tun ist.\n\nIhr kümmert Euch am besten wieder um das Wichtigste und versucht, Eure Halskette zu verstärken.\n\nIch werde Euch schon erreichen, wenn MUTTER und ich hier oben fertig sind.", sourceObjective = "Kehrt zu Nathanos Pestrufer an Bord der Klagelied in Zuldazar zurück.", completion = "Ihr seid zurück. Ich denke, wir finden hier etwas zu tun für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61872] = { id = 61872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktuelle Anliegen", description = "Ihr habt Euch hier gut geschlagen. MUTTER und ich überlegen uns, was als Nächstes zu tun ist.\n\nIhr kümmert Euch am besten wieder um das Wichtigste und versucht, Eure Halskette zu verstärken.\n\nIch werde Euch schon erreichen, wenn MUTTER und ich hier oben fertig sind.", sourceObjective = "Kehrt zu Halford Wyrmbann an Bord der Erlösenden Winde in Boralus zurück.", completion = "{name}, es ist gut, Euch wiederzusehen. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[61874] = { id = 61874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands: Eine eisige Vorladung", description = "Es ist Zeit, {class}.\n\nHochlord Bolvar Fordragon erbittet Eure Anwesenheit auf der Spitze der Eiskronenzitadelle. Trefft mich in Orgrimmar und ich bringe Euch zu ihm.\n\nIch würde ihn nicht warten lassen.", sourceObjective = "Trefft Darion Mograine vor der Feste Grommash in Orgrimmar.", completion = "Gut, dass Ihr gekommen seid.\n\nIn dieser dunklen Stunde brauchen wir Helden wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61875] = { id = 61875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Tau", description = "Der Disteltropfentau ist eine seltsame Kreatur. Die Wurzeln erstrecken sich tief in die Erde, wo sie uraltes Wasser aufsaugen. Mit diesem Wasser beziehen sie die Essenz des Landes selbst und speichern sie in einem Tropfen, mit dem unsere Handwerker mächtige Waffen herstellen können.\n\nWenn Ihr uns helft, den Tropfen zu sammeln, erwartet Euch eine Belohnung.\n\nAber Ihr müsst Euch eilen, damit er nicht verdunstet!", sourceObjective = "Sammelt 30 Disteltropfentau im Ardenwald.", progress = "Der Tau verdunstet schnell! Beeilung!", completion = "Dieser Tau wird unseren Handwerksmeistern sehr helfen!\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[61876] = { id = 61876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz fassen", description = "Mograine und ich haben uns bei seinem Besuch in der Bastion lange unterhalten. Er meinte, dass wir das Emblem des Aufstiegs mit Gharmals Herz verstärken können, wenn es uns gelingt, ihn zu töten.\n\nDer Markgraf besitzt die Macht, Formen zu bilden, wie es nur wenige können. Obwohl seine Resultate grausig sind, wären unsere Aufgestiegenen stärker denn je, wenn wir diese Macht kontrollieren könnten.\n\nDas ist nicht unser Weg, aber ich glaube, unser Weg verändert sich. Ein Schritt auf unserem neuen Pfad.", sourceObjective = "Sammelt das Herz des Fleischformers.", progress = "Es muss getan werden.", completion = "Ich bin erleichtert, dass ich dieses Ding nicht zurück zur Bastion tragen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[61877] = { id = 61877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Feste", description = "Bringen wir das Herz schnell zur Elysischen Feste.\n\nEs gibt viele in den Schattenlanden, die uns diese Macht entreißen wollen. Haltet die Augen offen.\n\nWir kehren siegreich zu Eurem Volk zurück.", sourceObjective = "Trefft Xandria am Emblem des Aufstiegs in der Elysischen Feste in der Bastion.", completion = "Ich bin froh, wieder unter Unseresgleichen zu sein. Maldraxxus schmeckt mir nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[61878] = { id = 61878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emblem der Grandeur", description = "Sobald Ihr bereit seid, müsst Ihr nur das Herz in dieser Sphäre auf dem Emblem des Aufstiegs platzieren.\n\nMikanikos' Arbeit wird sicherstellen, dass die Energie richtig kanalisiert wird, um unsere Rituale des Aufstiegs zu unterstützen. Seine Macht wird das Emblem vor Angriffen schützen.\n\nMöge das Haus der Konstrukte unser Reich nie wieder betreten.", sourceObjective = "Platziert das Herz des Fleischformers im Emblem des Aufstiegs.", progress = "<Das sieht wie die Kugel aus, in der Ihr auf Xandrias Anweisung hin das Herz platzieren sollt.>", completion = "<Das Herz des Fleischformers fügt sich in die leuchtende Kugel ein. Ein leisen Klicken ertönt aus dem Emblem, als ob es nur auf diese Macht gewartet hätte.\n\nDer Beginn einer neuen Ära für die Kyrianer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[61879] = { id = 61879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche wird fallen", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61880] = { id = 61880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noble Gäste", description = "Es ist mir eine Ehre, der erste Gast des Gluthofs zu sein.\n\nBitte informiert Prinz Renathal und alle Eure Gefährten, dass ich ganz sicher komme, wann auch immer Ihr Eure Tore öffnet.", sourceObjective = "Informiert Temel, dass Grufthüter Kassir am Gluthof teilnimmt.", completion = "Wenn Kassir kommt, stellen wir besser sicher, dass es eine förmliche Angelegenheit wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[61882] = { id = 61882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Förmliche Unterhaltung", description = "Die Anklägerin wird erfreut sein, dass Ihr für den ersten Gluthof solch bescheidene und förmliche Unterhaltung ausgewählt habt.\n\nIch freue mich auf diesen Anlass.", sourceObjective = "Informiert Temel, dass Ihr für Unterhaltung am Gluthof gesorgt habt.", completion = "Uralte Rituale? Solche Feste liebe ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[61883] = { id = 61883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstandsfähige Überlebende", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61884] = { id = 61884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Förmliche Erfrischungen", description = "Tubbins' Tee ist bald fertig. Sagt es Theotar und Freunden.\n\nTubbins ist der Beste!", sourceObjective = "Teilt Temel mit, dass Ihr für Erfrischungen am Gluthof gesorgt habt.", completion = "Tubbins bringt hoffentlich Gubbins. Er ist der Lustige!", sourceObjectiveStatus = "unverified-source-field" }
quests[61885] = { id = 61885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iiihgors besondere Freunde", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61886] = { id = 61886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Addius' Gedankenspielchen", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61892] = { id = 61892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthofbotschafter", description = "Euren Einfluss auszuweiten, ist recht einfach.\n\nFindet jemanden. Fragt ihn, was er will. Gebt es ihm.\n\nGlückwunsch. Jetzt habt Ihr Einfluss auf ihn.\n\nWenn wir die anderen Reiche auf unsere Seite ziehen wollen, müssen wir das Gleiche in größerem Maßstab tun.\n\nAlso besucht die anderen Reiche. Gebt ihnen, was sie wollen. Weitet unseren Einfluss aus.", sourceObjective = "Schließt Weltquests in den Schattenlanden ab.", completion = "Unsere Kontakte in den anderen Reichen haben bereits Gutes über Eure Taten dort aufgeschnappt.\n\n<Lady Ilinca lächelt.>\n\nUnser Einfluss wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[61893] = { id = 61893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthofbotschafter", description = "Euren Einfluss auszuweiten, ist recht einfach.\n\nFindet jemanden. Fragt ihn, was er will. Gebt es ihm.\n\nGlückwunsch. Jetzt habt Ihr Einfluss auf ihn.\n\nWenn wir die anderen Reiche auf unsere Seite ziehen wollen, müssen wir das Gleiche in größerem Maßstab tun.\n\nAlso besucht die anderen Reiche. Gebt ihnen, was sie wollen. Weitet unseren Einfluss aus.", sourceObjective = "Schließt Weltquests in den Schattenlanden ab.", completion = "Unsere Kontakte in den anderen Reichen haben bereits Gutes über Eure Taten dort aufgeschnappt.\n\n<Lady Ilinca lächelt.>\n\nUnser Einfluss wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[61894] = { id = 61894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthofbotschafter", description = "Euren Einfluss auszuweiten, ist recht einfach.\n\nFindet jemanden. Fragt ihn, was er will. Gebt es ihm.\n\nGlückwunsch. Jetzt habt Ihr Einfluss auf ihn.\n\nWenn wir die anderen Reiche auf unsere Seite ziehen wollen, müssen wir das Gleiche in größerem Maßstab tun.\n\nAlso besucht die anderen Reiche. Gebt ihnen, was sie wollen. Weitet unseren Einfluss aus.", sourceObjective = "Schließt Weltquests in den Schattenlanden ab.", completion = "Unsere Kontakte in den anderen Reichen haben bereits Gutes über Eure Taten dort aufgeschnappt.\n\n<Lady Ilinca lächelt.>\n\nUnser Einfluss wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[61895] = { id = 61895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluthofbotschafter", description = "Euren Einfluss auszuweiten, ist recht einfach.\n\nFindet jemanden. Fragt ihn, was er will. Gebt es ihm.\n\nGlückwunsch. Jetzt habt Ihr Einfluss auf ihn.\n\nWenn wir die anderen Reiche auf unsere Seite ziehen wollen, müssen wir das Gleiche in größerem Maßstab tun.\n\nAlso besucht die anderen Reiche. Gebt ihnen, was sie wollen. Weitet unseren Einfluss aus.", sourceObjective = "Schließt Weltquests in den Schattenlanden ab.", completion = "Unsere Kontakte in den anderen Reichen haben bereits Gutes über Eure Taten dort aufgeschnappt.\n\n<Lady Ilinca lächelt.>\n\nUnser Einfluss wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[61896] = { id = 61896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckter Sicherheitsdienst", description = "Wisst Ihr, warum die Venthyr Steingeborene in verschiedenen Formen meißeln?\n\nWeil Vielfalt an Form Vielfalt in der Strategie bedeutet. Unsere unterschiedlichen Formen geben uns unterschiedliche Bestimmungen.\n\nWir brauchen eine neue Form, um die höfische Verteidigung zu festigen.\n\nMit der richtigen Ausbildung und dem richtigen Werkzeug lassen sich Venthyrwachen in der Öffentlichkeit als Begrüßer tarnen.\n\nSie können sich unerkannt unter die Gäste mischen und im Falle einer Bedrohung sofort reagieren.", sourceObjective = "Sammelt den Übungsleitfaden \"Der Alltagsassassine\" in Maldraxxus und 20 verzauberten Trickserstaub im Ardenwald.", progress = "Verdeckte Wachen? Interessante Idee...", completion = "Das war der einfache Teil. Der schwere Teil ist, Wachen zu finden, die sich stundenlang das Geplapper der feinen Gesellschaft anhören wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61898] = { id = 61898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Happen", sourceObjective = "Sammelt verschiedene Käsesorten aus der Bastion und Hefevorteig für Sauerteigbrot aus Maldraxxus.", progress = "Seid Ihr sicher, dass Stefan der Wählerische ALLE diese Sachen wollte?", completion = "Die Faszination der Sterblichen für Käse werde ich nie verstehen... Sieht ekelhaft aus.\n\nAber Stefan der Wählerische bekommt, was Stefan der Wählerische will!", sourceObjectiveStatus = "unverified-source-field" }
quests[61899] = { id = 61899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaverkostungen", sourceObjective = "Sammelt frische Anima aus dem Ardenwald, der Bastion, Maldraxxus und Revendreth.", progress = "Das ist aber eine Menge Anima, die Ihr da habt. Ist das alles nur für Getränke?", completion = "Kuhl hat bereits einen Namen für die Meisterin der Anima geschickt, die die Verkostungen leiten soll.\n\nIch nehme sie unter das Personal auf und lasse das Zeugs an sie liefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[61900] = { id = 61900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemütliche Sessel", description = "Die Gäste sollen sitzen.\n\nStehen ist schwer. Ich weiß das, weil ich viel stehe.\n\nGäste sollen es gemütlich haben, im Sitzen.\n\nIch mache bequeme Sessel für alle Gäste.\n\nGäste sind zufrieden, bleiben länger!", sourceObjective = "Sammelt 30 weiches Vulpinfell aus der Bastion und 30 wiederbeschafftes Holz aus dem Ardenwald.", progress = "Schock weiß, was Sache ist. Wenn der sagt, wir sollen Stühle machen, dann machen wir Stühle.", completion = "<Temel muss das weiche Vulpinfell unbedingt betasten.>\n\nOoo, diese Sessel werden so gemütlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[61916] = { id = 61916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Feuerschaden", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, die großen Flammen von Kerzen haben alle Tischdecken verbrannt.\n\nHolt mir schönen Stoff und ich mach neue Tischdecken.\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "Guter Stoff. Tauch ich in Schlamm, um feuerfest zu machen.\n\nDekorationen sind jetzt für Euch bereit!" }
quests[61943] = { id = 61943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hofbeeinflusser", sourceObjective = "Dank Eurer Unterstützung des Gluthofs konnte ich diese Liste möglicher neuer Gäste zusammenstellen.\n\nSeht sie bitte durch und lasst mich wissen, wen wir als Erstes einladen sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[61944] = { id = 61944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exquisiter Geschmack", sourceObjective = "Eure Unterstützung des Gluthofs hat die Aufmerksamkeit einiger mächtiger Individuen auf sich gezogen, {name}.\n\nIch habe eine Liste dieser exklusiven Gäste aufgesetzt. Seht sie bitte durch und lasst mich wissen, wen wir als Erstes einladen sollten.\n\nIhr solltet wissen, dass es nicht einfach wird, diese anspruchsvollen Personen zufriedenzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61945] = { id = 61945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Profis", sourceObjective = "Betretet den Gluthof und gebt dann einem der Mitglieder des Expertenstabs Anweisungen.", completion = "Puh, diese Experten wissen, wie man Aufgaben erledigt!\n\nIch werde sicherstellen, dass sie ab jetzt bei jedem Gluthof dabei sind. Ihr müsst nur vorbeischauen und ihnen Anweisungen geben, bevor sich die Tore öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61946] = { id = 61946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geborene Verteidiger", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61947] = { id = 61947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schatten lauernd", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61948] = { id = 61948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftabwehr", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61949] = { id = 61949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trickser vom Ardenwald", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[61950] = { id = 61950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd in der Wildnis", description = "Die Versorgung mit eingestimmter Anima neigt sich schon wieder dem Ende zu. Es überrascht mich, dass unsere Ressourcen so lange ohne Nachschub gehalten haben.\n\nIhr habt Euch bei Suche nach Notwendigem bewiesen, vielleicht könnt Ihr uns wieder helfen?\n\nDie Runenhirsche, die durch den Ardenwald ziehen, sind von der Macht der Wildnis besonders durchströmt. Ihre Anima wäre perfekt für unsere Bedürfnisse.\n\nGute Jagd!", sourceObjective = "Sammelt 10 wilde Anima von Runenhirschen.", progress = "Macht Euch keine Sorgen um die Runenhirsche, sie kehren nach einiger Zeit zurück. Das gehört zum ewigen Zyklus.", completion = "Gut gemacht! Dank Eurer Anstrengungen kann unsere Produktion lange weitergehen.\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[61957] = { id = 61957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ashraka", sourceObjective = "Ich stehe Euch jetzt zu Diensten, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61958] = { id = 61958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Schlingbein", sourceObjective = "Ein neuer Meister. Jetzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[61959] = { id = 61959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Talethi", sourceObjective = "Ich werde meine Schulden bei meinem Schlundgänger begleichen.\n\nRichtet meine Kraft gegen Eure Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[61960] = { id = 61960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Xertora", sourceObjective = "Ihr habt nicht vielleicht ein Ersatzbein übrig? Ihr braucht doch bestimmte keine zwei. Ich werde es auch in Eurem Sinne einsetzen und Euren Feinden einen Tritt verpassen!\n\nNein? Aber ich kann wahrscheinlich trotzdem helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61961] = { id = 61961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rasselbeutel", sourceObjective = "Ich bin bereit für den Kampf!\n\nStellt mich in die erste Reihe. Ich werde Euer Schild sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[61962] = { id = 61962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Velkein", sourceObjective = "Ich werde wieder einmal meine Klinge aus gebührendem Anlass schwingen!\n\nTod Euren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[61963] = { id = 61963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Jagd gerufen", description = "Die Wilde Jagd besteht aus Fae, die ihr Leben dem Schutz des Ardenwalds und seiner Bewohner gewidmet haben. Jedes Mitglied hat unvergleichliche geschärfte Sinne und Fertigkeiten.\n\nWir haben mit einem Beschwörer und einer Jägerin gesprochen. Sie erlauben uns, ihre Erinnerungen für Übungszwecke festzuhalten, wenn wir ihnen bei einer besonderen Jagd helfen.\n\nTrefft Alderyn beim Klauenkamm. Er ist derjenige, den Ihr sucht.", sourceObjective = "Findet Alderyn beim Klauenkamm im Ardenwald.", progress = "Ihr seid nicht von hier. Wie kann ich Euch behilflich sein?", completion = "Der Gesandte der Kyrianer, mit der perfekten Waffe ausgestattet, um die Rüstung unserer Beute zu durchdringen\n\nSeid Ihr bereit für eine Jagd?", sourceObjectiveStatus = "unverified-source-field" }
quests[61964] = { id = 61964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aubries wöchentliche Quest: Turm des Kerkermeisters" }
quests[61965] = { id = 61965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stoß durch den Panzer", description = "Unsere Beute ist einer der Gorm, einheimische Wesen, die einst hilfreich für das Reich waren, bis die Dürre sie in den Wahnsinn getrieben hat.\n\nDieses spezielle Exemplar ist zu furchterregender Größe angewachsen und hat einen Panzer, der so dick ist, dass ihn keine unserer Waffen oder Pfeile durchdringen kann.\n\nEuer Speer, der mit der Anima der Bastion durchtränkt ist, könnte genau die Waffe sein, die seinen Panzer durchstoßen und den Gorm töten kann.\n\nMeine Schwester ist vorangegangen und kundschaftet alles aus. Gehen wir.", sourceObjective = "Findet Myn'ir im Gormnest und tötet dann den verstärkten Austrockner.", completion = "Der Schrecken ist erlegt. Eure Hilfe und Euer Speer waren äußerst nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[61967] = { id = 61967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhilfestunden" }
quests[61968] = { id = 61968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beflügelte Suche", description = "Seit ewigen Zeiten schon stellt die bescheidene Ardenmotte die Schuppen für die Rüstungsfertigung der Wilden Jagd.\n\nJetzt, da unsere Aufmerksamkeit zwischen den Bedrohungen dieses Reichs und der Animadürre aufgeteilt ist, fällt es unseren Wildbeutern immer schwerer, die Schuppen zu finden, die wir benötigen.\n\nNur Schuppen allerfeinster Qualität können verwendet werden. Sollten Euch auf Euren Reisen welche begegnen, bringt sie mir und Ihr werdet reich entlohnt.", sourceObjective = "Sammelt 28 perfekte Ardenmottenflügelschuppen.", progress = "Habt Ihr die Schuppen?", completion = "Ah, bemerkenswerte Qualität! Das habt Ihr gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[61981] = { id = 61981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir auffüllen", description = "Also, so sieht's aus: Wir brauchen Anima.\n\nNicht nur ein bisschen oder eine Prise, sondern eine Menge. Wisst Ihr, ohne Anima kann man nix Lohnenswertes tun. Nicht in den Schattenlanden. Nicht, wenn wir diesen Schlamassel wieder hinbiegen wollen, den wir Denathrius zu verdanken haben.\n\nUnd da Ihr ein findiger Kopf seid, müsst ihr für uns betteln, borgen, stehlen, klauen, einbrechen, pulverisieren, piratisieren, verdienen, betrügen oder anderweitig die Quelle großer Wohltätigkeit für alle Anima werden, die Ihr in die Griffel bekommen könnt.\n\nBringt mir Anima und ich werde damit unsere Schatzkammern auf den alten Stand bringen, damit Ihr sie sinnvoll einsetzen könnt.", sourceObjective = "Sammelt Animaquellen für das Animareservoir in Sündensturz in Revendreth.", completion = "Das ist ja mal ein echter Profi-Job. Mit dieser Anima werden wir im Handumdrehen schicke Sachen machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[61982] = { id = 61982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir auffüllen", description = "Seid gegrüßt, <Schlundgänger/Schlundgängerin>.\n\nIn dem Maße, wie unser Einfluss auf die Bastion wächst, wächst auch unser Bedarf an unserem wertvollsten Rohstoff: Anima.\n\nWir müssen unsere Reserven auffüllen. Sucht in den Reichen nach so viel wie möglich davon und bringt die Anima hierher zurück.\n\nIst sie aufgefüllt, können wir sie dann dorthin schicken, wo sie am dringendsten gebraucht wird.\n\nGeht und dient, {class}.", sourceObjective = "Sammelt Animaquellen für das Animareservoir in der Elysischen Feste in der Bastion.", completion = "Euch gebührt mein Dank, Schlundgänger. Wir werden sie nicht vergeuden.", sourceObjectiveStatus = "unverified-source-field" }
quests[61983] = { id = 61983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir auffüllen", description = "Wir sind auf Eure Stärke angewiesen, <Schlundgänger/Schlundgängerin>.\n\nDie Häuser unserer Gegner werden von Stunde zu Stunde mächtiger. Für unseren Angriff benötigen wir neue Animaquellen, um unsere Reserven aufzufüllen.\n\nDurchsucht die Reiche nach dieser wertvollen Ressource und bringt sie hierher zum Sanktum. Niemand soll Euch trotzen!\n\nMit Eurer Hilfe werden die konkurrierenden Häuser eins nach dem anderen fallen, und wir triumphieren!", sourceObjective = "Sammelt Animaquellen für das Animareservoir im Sitz des Primus in Maldraxxus.", completion = "Eure Beiträge sichern uns den Sieg in der Schlacht. Der letzte Triumph wird unser sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[61984] = { id = 61984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir auffüllen", description = "Seid gegrüßt, <Schlundgänger/Schlundgängerin>.\n\nTirna Achiad, Herz des Ardenwalds, gedeiht in unserer Obhut, doch für unser Sanktum wird noch mehr Anima benötigt.\n\nDer Zyklus der Wiedergeburt, unsere Bestimmung, muss weitergehen.\n\nWir müssen mehr besorgen, um unserer Königin zu dienen. Helft Ihr uns, das Reservoir aufzufüllen?", sourceObjective = "Sammelt Animaquellen für das Animareservoir im Herz des Waldes im Ardenwald.", completion = "Die durch Euch bereitgestellte Anima wird der Pflege unserer kostbaren Haine dienen. Wir danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[61985] = { id = 61985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlafenden erwecken", description = "Das Land spricht zu mir, {name}. Der Ardenwald ist ein Reich der Zyklen, aber er hatte es noch nie mit einer solchen Animadürre zu tun.\n\nWir brauchen die Hilfe aller Bewohner, wenn wir es durch diese Krise schaffen wollen.\n\nViele Seelen schlummern in den Wäldern und Hügeln. Wenn sie uns etwas von ihrer Anima abgeben könnten, könnten wir etwas länger durchhalten. Sollten Euch auf Euren Reisen Seelen begegnen, erweckt sie bitte und schickt sie zu mir.", sourceObjective = "Erweckt 8 schlummernde Seelen.", completion = "Dieser Tau wird unseren Handwerksmeistern sehr helfen!\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[61996] = { id = 61996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt die Zauberworte", description = "Seit ich meinen ersten Zauber gewirkt habe, konnte ich von Magie nicht genug bekommen!\n\nEs ist nicht so schwer, wie die ganzen Lichs behaupten. Ihr fokussiert Eure Gedanken, sprecht die Worte, und dann passiert Magie!\n\nEs gibt Folianten in Archivam in Revendreth, die uralte Zauber dokumentieren. Helft mir, sie einzusammeln, damit ich ein paar neue Zauber lernen kann!", sourceObjective = "Helft Sabrina, 12 neue Zauber in Revendreth zu erlernen.", completion = "Ihr habt uns geholfen, unsere Truppen zu stärken, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[61998] = { id = 61998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinernes Vermächtnis", progress = "Hier haben wir noch Platz für eine weitere große Statue.\n\nBesorgt mir etwas Stein und ich mach Euch die Statue, die Ihr wollt, ja?\n\nVielleicht eine von Euch oder jemand anderem, ja?", completion = "Sagt mir, was für eine Skulptur ich für Euch machen soll!" }
quests[62000] = { id = 62000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahl Eurer Vorsehung", description = "Die Pakte sind für die Schattenlande unerlässlich. Auch wenn sie in letzter Zeit isoliert und gespalten waren, stützt die Vorsehung sich auf den Erfolg ihrer Bemühungen.\n\nAlle Pakte müssen sich verstärken, um sich der Bedrohung durch den Verbannten entgegenzustellen. Aber Eure Mitwirkung kann nicht aufgeteilt werden. Sie muss sich auf einen einzigen Weg konzentrieren. Andere Sterbliche können eine andere Wahl treffen.\n\nSprecht mit Euren möglichen Verbündeten. Dann trefft Eure Wahl auf der Karte der Schattenlande vor mir.", sourceObjective = "Sprecht mit den Pakten. Entscheidet, wie Euer Pfad mit der Vorsehung zusammenhängt.", progress = "Habt Ihr Eure Entscheidung gefällt?", completion = "Alles ist wie erwartet. Vertraut immer auf die Weisheit der Richterin.", sourceObjectiveStatus = "unverified-source-field" }
quests[62041] = { id = 62041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In schlechtem Licht", description = "Ich habe von dem Chaos in Revendreth gehört. Berichte von Exilanten, die in den Wahnsinn getrieben und in der Austrocknung verbrannt wurden.\n\nAllein der Gedanke an all dieses Leid drängt mich dazu, etwas zu unternehmen.\n\nWenn Ihr auf dem Wege dorthin seid, würde ich Euch gern begleiten. Ich muss einfach so vielen helfen, wie ich nur kann!", sourceObjective = "Verwendet Rosenpustels regenerative Häutung, um 15 lichtversengte Exilanten zu kurieren.", completion = "Leid ist wahrlich nichts Neues für die Einwohner von Revendreth, aber Ihr und Rosenpustel konntet trotzdem einigen helfen.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62043] = { id = 62043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Wert", description = "Ihr müsst uns erneut Euren Wert beweisen, {name}.\n\nWir haben Euren Verrat noch nicht vergessen.\n\nUnd doch sprecht Ihr von Eurer Sühne. Mit der Erledigung dieser Aufgabe könnt Ihr anfangen zu beweisen, dass Ihr aufrichtig unser Vertrauen zurückerlangen wollt.", sourceObjective = "Schließt die Aufgabe der Kyrianer ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?\n\nWenn Ihr diese Aufgabe bei mir abschließt, werdet Ihr Euren derzeitigen Pakt verlassen und Euch wieder den Kyrianern anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62044] = { id = 62044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Angesicht zu Angesicht", description = "<Der Fresser ist deutlich größer und nickt mit seinem Kopf in Richtung eines anderen Fressers, als ob er will, dass Ihr ihn angreift.>", sourceObjective = "Besiegt Verschlingerfresser.", completion = "<Ihr könnt im \"Gesicht\" des Fressers keine Regung ausmachen, aber es scheint, als wäre er sehr von sich überzeugt. So, als ob er die anderen selbst besiegt hätte. Er bietet Euch etwas Glänzendes an, das er gefunden hat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[62045] = { id = 62045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für mehr", description = "<Der Fresser stolziert wieder kampfbereit herum und starrt den nächsten Fresser nieder.>", sourceObjective = "Besiegt Verschlingerfresser.", progress = "Greift Verschlingerfresser im Endmorast an und besiegt sie.", completion = "<Der Fresser plustert sich auf und glaubt sichtlich, dass er und Ihr ein hervorragendes Team abgebt. Er schaut zu Euch auf... und würgt etwas hoch, von dem er denkt, es könnte Euch gefallen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[62046] = { id = 62046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Rudel", description = "<Der Fresser ist mehr als ausgewachsen und übertrifft die meisten anderen Verschlinger in der Gegend. Er will offensichtlich bei Euch bleiben, aber es scheint ihm auch nicht wohl dabei, sich zu weit von den anderen Weltenfressern zu entfernen. Wenn Ihr einen gemeinsam erlegt, hat das vielleicht nicht mehr so viel Wirkung auf den Fresser.>", sourceObjective = "Besiegt einen ungebetenen Weltenfresser.", progress = "Besiegt einen ungebetenen Weltenfresser im Endmorast.", completion = "<Der Fresser ist außer sich vor Freude, dass Ihr einen Weltenfresser getötet habt. Seine Begeisterung ist spürbar, und er ist drauf und dran, Euch zu schnappen und zum nächsten Abenteuer zu tragen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[62051] = { id = 62051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormlingwerfen: Geistertal" }
quests[62052] = { id = 62052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbannung durch Paranoia", description = "Die Lichs des Hauses der Rituale waren ein wichtiger Faktor beim Angriff der Maldraxxi auf die Bastion. Sie sind aktuell keine Verbündeten, und es wäre schwierig, einen davon zu überzeugen, seine Erinnerung für Übungszwecke festzuhalten zu dürfen.\n\nWir sind in Kontakt mit einer Totenbeschwörerin, die noch eine Rechnung mit einem der Lichs offen hat. Findet sie, und sie wird Euch dabei helfen, diese Erinnerung festzuhalten.", sourceObjective = "Findet Karaxi die Abtrünnige auf der Herausfordererpromenade in Maldraxxus.", progress = "<Karaxi blättert sehr vorsichtig durch ein Buch.>", completion = "Mein Plan trägt wirklich Früchte. Ein Fremdling, der hier ist, um mir bei meiner Rache zu helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[62053] = { id = 62053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekromantische Macht", description = "Meine alte Meisterin, Thran'tiok, ist der Inbegriff der Paranoia. Sie glaubt, dass jeder sie verraten will, und aus diesem Grund musste ich nicht nur aus ihren Diensten ausscheiden, sondern sogar das Haus der Rituale verlassen.\n\nIch wollte keinen Streit mit ihr... aber das hat sich jetzt geändert.\n\nNehmt das Kristallgehäuse, das Ihr gebaut habt, und tötet meine alten Kollegen, um es mit nekromantischer Energie zu füllen. Es wird Euch zu Thran'tioks Phylakterium führen, also genau zu dem, was wir suchen.", sourceObjective = "Ladet den Seelensucherkristall auf, indem Ihr die Gegner im Haus der Rituale besiegt, und verwendet es dann, um Thran'tioks Phylakterium zu finden.", completion = "Wir haben nicht viel Zeit. Thran'tiok selbst wird bald auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62054] = { id = 62054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schloss Nathria: Kopfarbeit", description = "Wir müssen Denathrius zeigen, dass wir es ernst meinen. Sein Gräber... Haustier... sollte genügen.\n\nBringt mir seinen Kopf. Viermal sollte reichen. Gräber sind seltsame Wesen.", sourceObjective = "Sammelt 4 Schlickfaustköpfe in Schloss Nathria auf dem Schwierigkeitsgrad 'Normal'.", progress = "Ich brauche die Köpfe, sonst können wir keine deutliche Nachricht hinterlassen.", completion = "Mit denen ist uns die Aufmerksamkeit von Graf Denathrius sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[62055] = { id = 62055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schloss Nathria: Kopfarbeit", description = "Wir müssen Denathrius zeigen, dass wir es ernst meinen. Sein Gräber... Haustier... sollte genügen.\n\nBringt mir seinen Kopf. Viermal sollte reichen. Gräber sind seltsame Wesen.", sourceObjective = "Sammelt 4 Schlickfaustköpfe in Schloss Nathria auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Ich brauche die Köpfe, sonst können wir keine deutliche Nachricht hinterlassen.", completion = "Mit denen ist uns die Aufmerksamkeit von Graf Denathrius sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[62056] = { id = 62056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schloss Nathria: Kopfarbeit", description = "Wir müssen Denathrius zeigen, dass wir es ernst meinen. Sein Gräber... Haustier... sollte genügen.\n\nBringt mir seinen Kopf. Viermal sollte reichen. Gräber sind seltsame Wesen.", sourceObjective = "Sammelt 4 Schlickfaustköpfe in Schloss Nathria auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Ich brauche die Köpfe, sonst können wir keine deutliche Nachricht hinterlassen.", completion = "Mit denen ist uns die Aufmerksamkeit von Graf Denathrius sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[62057] = { id = 62057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hungernden", description = "Ich habe Berichte darüber gehört, dass die Anzahl der Gormsichtungen in den letzten Tagen stark angestiegen ist.\n\nNormalerweise sind sie einfache Zersetzer und erfüllen ihre Rolle im großen Kreislauf. Aber in großen Zahlen können die Gorm aggressiv werden, und wenn man ihnen keinen Einhalt gebietet, sorgt ihr unstillbarer Hunger für unsagbare Zerstörung.\n\nDie Wilde Jagd hat zur Gormjagd aufgerufen. Erfüllt Eure Quote, und Ihr werdet reich entlohnt.", sourceObjective = "Zerstört 20 Gorm im Ardenwald.", completion = "Ah, gute Arbeit. Die Gorm erfüllen ihren Zweck, aber wie überall muss das Gleichgewicht gewahrt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62058] = { id = 62058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenturionen, sammelt Euch!" }
quests[62059] = { id = 62059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Wert", description = "Ihr müsst uns erneut Euren Wert beweisen, {name}.\n\nWir haben Euren Verrat noch nicht vergessen.\n\nUnd doch verlangt es Euch nach Sühne. Diese Aufgabe sollte beweisen, dass Ihr gewillt seid, Euch uns wieder anzuschließen.", sourceObjective = "Schließt die Aufgabe der Nekrolords ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?\n\nWenn Ihr diese Aufgabe bei mir abschließt, werdet Ihr Euren derzeitigen Pakt verlassen und Euch wieder den Nekrolords anschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62060] = { id = 62060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Wert", description = "Ihr müsst uns erneut Euren Wert beweisen, {name}.\n\nWir haben Euren Verrat noch nicht vergessen.\n\nUnd doch verlangt es Euch nach Sühne. Diese Aufgabe sollte beweisen, dass Ihr gewillt seid, Euch uns wieder anzuschließen.", sourceObjective = "Schließt die Aufgabe der Nachtfae ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[62061] = { id = 62061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Wert", description = "Ihr müsst uns erneut Euren Wert beweisen, {name}.\n\nWir haben Euren Verrat noch nicht vergessen.\n\nUnd doch verlangt es Euch nach Sühne. Diese Aufgabe sollte beweisen, dass Ihr gewillt seid, Euch uns wieder anzuschließen.", sourceObjective = "Schließt die Aufgabe der Venthyr ab.", completion = "Ihr habt also getan, wozu wir Euch aufgefordert haben, und wollt Euch uns erneut anschließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[62062] = { id = 62062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Gestohlene Teppiche", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, diese Diebe stehlen mehr als Erinnerungen. Sie stehlen auch Teppiche!\n\nNeue Teppiche werden so schwer, dass Diebe nicht tragen können! Holt mir Dinge, um schwere Teppiche zu machen.\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "Ha! Neue Teppiche werden schwer und hübsch... wie ich.\n\nDekorationen sind jetzt für Euch bereit!" }
quests[62064] = { id = 62064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Zerbrochene Spiegel", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, diese Gefangenen haben alle Spiegel bei der Flucht zerbrochen!\n\nLaurent hilft mir, aber brauche Teile.\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "Mit reparierten Spiegeln kann ich mein hübsches Gesicht wieder sehen.\n\nDekorationen sind jetzt für Euch bereit!" }
quests[62065] = { id = 62065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Mein Lieblingstisch", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, einer dieser großen bösen Gräber sitzt auf meinem Lieblingstisch, zerbricht in zwei Hälften!\n\nBrauch Holz, um Tisch zu reparieren.\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "Ich geh ganz sicher, dass keine großen bösen Gräber mehr auf meinem Tisch sitzen.\n\nDekorationen sind jetzt für Euch bereit!" }
quests[62066] = { id = 62066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Gräberbecken", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, schleimt die große Schleimkugel Schleim in unsere Schlammlache. Jeder neue Gräber voll Schleim!\n\nMuss alles schlechte Zeug loswerden... Kennt Ihr was, das das macht?\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "In Ordnung... Ich schütte in Schlammlache und schau, ob's hilft.\n\nDekorationen sind jetzt für Euch bereit!" }
quests[62067] = { id = 62067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Statuen", progress = "Dekorationen nicht bereit!\n\nLetzter Gluthof, alle Gräber sehen große neue Statue. Jetzt wollen alle Statue!\n\nHolt mir Stein und ich mach kleine Statuen zum Halten.\n\nDann können wir Dekorationen für nächsten Hof aussuchen.", completion = "Vielleicht mache ich auch für den Prinz. Mag er Statuen, ja?\n\nDekorationen sind jetzt für Euch bereit!" }
quests[62068] = { id = 62068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormlingfänger: Zerfallener Grat" }
quests[62069] = { id = 62069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Sündensteine", progress = "Wir haben ein Problem, {name}.\n\nBeim letzten Gluthof waren die Rituale der Anklägerin ein wenig ZU überzeugend. Einige meiner Gräber wollen jetzt ihre eigenen Sündensteine, damit sie Dinge auflisten können, von denen sie denken, dass sie falsch waren.\n\nIch werde einige Ressourcen benötigen, um ihr Schuldbewusstsein zu besänftigen.\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Ich kann kaum glauben, dass wir das wirklich tun... Aber ich bin neugierig zu sehen, was sie aufgelistet haben.\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62070] = { id = 62070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Duftende Blumen", progress = "Es gibt da ein Problem, {name}.\n\nBeim letzten Gluthof war was mit den Tieren... nicht in Ordnung. Ich krieg die Flecken nicht raus und alles stinkt!\n\nIch brauche ein paar duftende Blumen, um den Gestank zu überdecken.\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Die riechen super! Oder zumindest besser als dieser Gestank hier...\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62073] = { id = 62073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Bandhemden", progress = "Es gibt da eine gute Gelegenheit, {name}.\n\nDie Band \"Der Verschüttete Kelch\" ist nach der irren Vorstellung beim letzten Gluthof die heißeste Unterhaltungsnummer in Revendreth. Alle reden über die.\n\nWir sollten ein paar Bandhemden anfertigen und kostenlos verteilen lassen, um den Hype weiter anzufeuern.\n\nBringt mir die Materialien, und ich kümmer mich um den Rest.\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Bald wird die gesamte feine Gesellschaft in Revendreth die Dinger tragen und damit Werbung für unseren Gluthof machen.\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62074] = { id = 62074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "Ihr habt etwas gefunden, das eine Art Erinnerung zu sein scheint. Vielleicht ist es eine weitere gestohlene Erinnerung des Runenmetzes.", sourceObjective = "Bringt die Erinnerung dem Runenmetz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62075] = { id = 62075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Seelengefängnisse", progress = "Es gibt da ein Problem, {name}.\n\nBeim letzten Gluthof konnten wir eine ganze Menge von diesen misshandelten Seelen, mit denen uns die Schergen des Meisters angegriffen haben, retten.\n\nDas ist eine gute Sache, aber wir brauchen mehr Ketten und Käfige, um die hier einzusperren, bis die Anklägerin sich um sie kümmert.\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Ich bring die Ritualisten dazu, uns beim Bau der Käfige zu helfen, damit da nix schief geht.\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62076] = { id = 62076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Freie Presse", progress = "Es gibt da ein Problem, {name}.\n\nBeim letzten Gluthof hat sich das Gerede von diesem Provokateur weiter verbreitet als gedacht. Ich krieg hier jede Menge nervige Fragen aus der feinen Gesellschaft und von Adligen rein, die nicht wissen, was sie davon halten sollen.\n\nWir müssen ein Schreiben aufsetzen, um die Sache klarzustellen und diesem verlogenen Stinktier das Maul zu stopfen!\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Briefe schreiben: Eine der ältesten Formen der Unterhaltung.\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62078] = { id = 62078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Modeaccessoires", progress = "Es gibt da ein Problem, {name}.\n\nBeim letzten Gluthof hat die Tuchmacherin der Gräfin die Mode der Zukunft vorgestellt und wir hängen voll hinterher. Medaillons sind der neueste Kreisch, dank der wachsenden Sammlung des Prinzen.\n\nIch komm an kein Medaillon ran, aber ich brauch zumindest eine Halskette, damit die mich beim nächsten Hof nicht auslachen.\n\nDann können wir unsere Unterhaltung für den nächsten Gluthof auswählen.", completion = "Ich kann kaum glauben, dass ich diese protzige Halskette tragen soll, aber wenn es sein muss, damit wir immer Zugriff auf die beste Unterhaltung haben...\n\n<Kuhl seufzt.>\n\nWir können die nächste Unterhaltung buchen, wenn Ihr bereit seid." }
quests[62080] = { id = 62080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Kräutertee", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nWährend des letzten Gluthofs haben die Gäste mehr Tee als Theotar selbst getrunken! Unsere gesamten Vorräte sind aufgebraucht.\n\nIch benötige dringend neue Teezutaten, und zwar von höchster Qualität!\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "Ah, daraus lässt sich ein hervorragender Tee bereiten, wenn ich alles getrocknet habe.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
quests[62081] = { id = 62081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückt die Animazapfen raus!", description = "Berichten zufolge machen die Spriggans schon wieder Ärger, {name}.\n\nEine Gruppe von ihnen soll in die Lager im Herzen des Waldes eingebrochen sein und sich mit einem riesigen Vorrat an Animazapfen davongemacht haben.\n\nEs versteht sich von selbst, dass wir diese Animazapfen zurückholen müssen.\n\nDen Berichten zufolge hat sich die Gruppe nach ihrer Flucht aufgeteilt, also sollten alle Mitglieder dieser Gruppe den ein oder anderen Animazapfen dabei haben.\n\nViel Glück.", sourceObjective = "Sammelt 44 geplünderte Animazapfen von Spriggans im Ardenwald.", progress = "Konntet Ihr die Animazapfen finden?", completion = "Ihr habt sie alle besorgen können? Das ist hervorragend!", sourceObjectiveStatus = "unverified-source-field" }
quests[62082] = { id = 62082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Persönliche Vorräte", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nWährend des letzten Gluthofs, als die Gäste mit Speisen um sich geworfen haben, flogen ein paar schlecht gezielte Kuchen in meine persönlichen Nahrungsmittelvorräte und haben alles ruiniert!\n\nIhr wisst, dass ich normalerweise nicht kleinlich bin, aber dieses Mal bestehe ich darauf, dass mir die durch die Essensschlacht ruinierten Delikatessen erstattet werden.\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "Ich danke Euch. Ich bin nicht nachtragend.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
quests[62083] = { id = 62083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Medizinische Versorgungsgüter", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nWährend des letzten Gluthofs haben die Hälfte der feinen Gesellschaft und ich selbst Vergiftungen durch die Wildpilze, die Ihr geliefert habt, erlitten.\n\nZum Glück handelt es sich dabei nicht um tödliche Vergiftungen, aber es ist trotzdem für alle Beteiligten unangenehm.\n\nWir brauchen dringend ein Gegengift.\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "<Stefan der Wählerische hält sich die Nase zu und trinkt aus der Phiole.>\n\nIch war noch nie so entschlossen, etwas zu mir zu nehmen, was so grässlich schmeckt.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
quests[62084] = { id = 62084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Edles Besteck", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nWährend des letzten Gluthofs haben die Venthyr nicht nur unsere Gäste angegriffen, sondern auch unser Besteck gestohlen.\n\nMein alter Freund Schmiedi kann uns neues Besteck anfertigen, aber wir müssen ihm die erforderlichen Vorräte liefern!\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "Das alte Besteck hätte ohnehin ersetzt werden müssen.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
quests[62085] = { id = 62085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...Warum ich?", description = "<Die dichte, klumpige Flüssigkeit in dem Gefäß sondert einen grauenvollen Gestank ab.\n\nAuf der Seite stehen die Initialen \"A.K.\". Offensichtlich hat jemand die Feldflasche von Aufseher Kalvaros gestohlen.>", sourceObjective = "Bringt das zurückgeholte Gefäß zu Aufseher Kalvaros auf der Herausfordererpromenade.\n\nBereitgestellter Gegenstand:", completion = "Ich hab meine Feldflasche schon vermisst. Wo habt Ihr sie gefunden, {name}? Habt Ihr davon getrunken, bevor Ihr zurückgekehrt seid?\n\nAber ist wohl auch egal.", sourceObjectiveStatus = "unverified-source-field" }
quests[62086] = { id = 62086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "Ihr habt etwas gefunden, das eine Art Erinnerung zu sein scheint. Vielleicht ist es eine weitere gestohlene Erinnerung des Runenmetzes.", sourceObjective = "Bringt die Erinnerung dem Runenmetz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62087] = { id = 62087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Importiertes Geschirr", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nWährend des letzten Gluthofs haben die Steinscheusale mehr als nur Theotars Teeservice fallengelassen. Sie haben auch das Geschirr zerschmettert, das ich direkt aus dem Ardenwald importiert hatte, damit sich unsere Gäste von den Nachtfae wie Zuhause fühlen.\n\nIch glaube, dass ich es reparieren kann, aber dafür brauche ich die entsprechenden Ressourcen.\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "Ich bin mir sicher, dass die Nachtfae all den Aufwand, den wir nur für sie betrieben haben, zu schätzen wussten.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
