quests[62093] = { id = 62093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "Ihr habt etwas gefunden, das eine Art Erinnerung zu sein scheint. Vielleicht ist es eine weitere gestohlene Erinnerung des Runenmetzes.", sourceObjective = "Bringt die Erinnerung dem Runenmetz zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62094] = { id = 62094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Innovative Mahlzeiten", progress = "In der Küche herrscht schon wieder Krisenzustand, Schlundgänger!\n\nIhr wisst sicher noch, wie dieser Mückenschwarm über unseren letzten Gluthof hergefallen ist. Obwohl es mir anfangs widerstrebte, habe ich mir Gedanken gemacht, welchen kulinarischen Nutzen diese kleinen Tierchen bieten könnten.\n\nIch möchte versuchen, ein paar Mahlzeiten aus ihnen zuzubereiten. Ich benötige allerdings ein paar Dinge, um mich auf dieses kulinarische Abenteuer vorzubereiten.\n\nDanach können wir gern über die Erfrischungsmöglichkeiten für unseren nächsten Hof sprechen.", completion = "Wünscht mir Glück... denn ich fürchte, ich werde es brauchen.\n\nJetzt können wir über die Erfrischungsmöglichkeiten für unseren nächsten Gluthof sprechen." }
quests[62095] = { id = 62095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Sanitäterzelt", progress = "Ich habe etwas Dringendes zu besprechen.\n\nDie freiwilligen Helfer beim Sicherheitsdienst des letzten Gluthofs waren zwar unglaublich tapfer, aber nicht auf die Härte solcher Kämpfe vorbereitet. Sie haben erhebliche Verletzungen erlitten.\n\nWir müssen unser medizinisches Personal erweitern, damit wir den nächsten Gluthof vorbereiten können.\n\nNachdem dies erledigt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Ich danke Euch. Die Versorgung der Verwundeten ist ein ehrenvolles Unterfangen.\n\nJetzt stehen uns wieder alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
quests[62096] = { id = 62096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professions - Reuse", description = "Ihr habt etwas gefunden, das eine Art Erinnerung zu sein scheint. Vielleicht ist es eine weitere gestohlene Erinnerung des Runenmetzes.", sourceObjective = "Bringt die Erinnerung dem Runenmetz zurück.", sourceObjectiveStatus = "unverified-source-field" }
