quests[62104] = { id = 62104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Steingeborene Reserven", progress = "Ich habe etwas Dringendes zu besprechen.\n\nAuf dem letzten Gluthof haben viele unserer Steingeborenen bei der Verteidigung unserer Gäste Frakturen und Verletzungen an den Gliedmaßen erlitten. Wir müssen sie reparieren.\n\nBringt mir die Steine, dann werde ich die Reparaturen mit den Gräbern koordinieren.\n\nNachdem dies erledigt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Das sollte ausreichen, um die gefallenen Steingeborenen wiederaufzubauen.\n\nJetzt stehen uns wieder alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
quests[62105] = { id = 62105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Unkonventionelle Waffen", progress = "Ich habe etwas Dringendes zu besprechen.\n\nDer Kampf an der Seite der Truppen aus Maldraxxus auf dem letzten Gluthof hat mich inspiriert, ein paar neue, für die Venthyr untypische Kriegsstrategien zu ersinnen.\n\nIch bin mir sicher, dass Ihr Sterblichen ein paar kreative Waffen entwickelt habt. Bringt mir einige davon, damit ich etwas von ihnen lernen kann.\n\nNachdem dies erledigt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Interessant. Ich hätte nicht gedacht, dass sie so... mechanisch sind.\n\nJetzt stehen uns wieder alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
quests[62106] = { id = 62106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Verzauberungen", progress = "Ich habe etwas Dringendes zu besprechen.\n\nDer Überraschungsangriff der Steinlegion auf unseren letzten Gluthof hat gezeigt, dass ich bei der Versorgung unserer Truppen mit Verzauberungen viel zu nachlässig war. Wir müssen jeden uns zur Verfügung stehenden Vorteil nutzen.\n\nBringt mir alle Verzauberungen, die Ihr uns überlassen könnt.\n\nNachdem dies erledigt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Wenn die Steinlegion wieder angreift, werden wir vorbereitet sein.\n\nJetzt stehen uns wieder alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
quests[62108] = { id = 62108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Strategische Kodexe", progress = "Ich habe etwas Dringendes zu besprechen.\n\nAuf dem letzten Gluthof konnte der Verschlinger unsere Wachen mit seiner Angriffstaktik überrumpeln. Die Portale hatten sich überall um uns herum geöffnet und wir waren nicht in der Lage, angemessen zu reagieren.\n\nWir sollten unsere Vorräte auffüllen, damit wir für solch dynamische Umstände in Zukunft gewappnet sind.\n\nNachdem dies erledigt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Auch Steingeborene können sich mit der Zeit ändern.\n\nJetzt stehen uns wieder alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
quests[62109] = { id = 62109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auffüllen: Überwachungsausrüstung", progress = "Ich habe etwas Dringendes zu besprechen.\n\nWie Ihr wisst, ist beim letzten Gluthof ein Mord geschehen. Das ist ein inakzeptables Versagen meinerseits, und dafür entschuldige ich mich.\n\nIch möchte gern zusätzliche Überwachungsausrüstung erwerben, um sicherzustellen, dass wir für einen solchen Fall vorbereitet sind.\n\nNachdem dies geklärt ist, können wir die Sicherheitsauswahl für zukünftige Gluthöfe besprechen.", completion = "Ich toleriere viele fragwürdige Aktivitäten beim Hof, aber Mord gehört nicht dazu.\n\nJetzt stehen uns alle Möglichkeiten der Sicherheitsauswahl zur Verfügung." }
