quests[62148] = { id = 62148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es regnet Anima" }
quests[62155] = { id = 62155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runensteinrandale", description = "Stein ist ein seltenes Material im Ardenwald. Und doch habe ich Geschichten gehört, dass die von den Drust Maskierten kleine Steine bei sich tragen.\n\nIch möchte, dass Ihr solche Steine für die Wilde Jagd holt, damit wir ihre Verbindung zu unserem Feind besser verstehen.\nStellt die Maskierten, sammelt die Steine von ihren Leichen, und ich werde Euch für Eure Mühen entlohnen.\n\nEine grausige Aufgabe, aber sie muss erledigt werden.", sourceObjective = "Sammelt 18 Runensteinstacheln von von den Drust besessenen Fae im Ardenwald.", progress = "Wie laufen Eure Untersuchungen?", completion = "Ihr habt sie alle besorgen können? Das ist hervorragend!", sourceObjectiveStatus = "unverified-source-field" }
quests[62157] = { id = 62157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrachtung aus sicherer Entfernung", description = "Das Wiederaufleben der Geißel ist beunruhigend genug, aber es gibt auch Berichte, dass der Kult der Verdammten ebenfalls wieder auferstanden ist.\n\nWenn das stimmt, dann verheißt das für uns alle nichts Gutes. Wir können nicht zulassen, dass die Machenschaften der Kultisten unkontrolliert weitergehen.\n\nIch schlage vor, wir begeben uns auf Erkundungstour.", sourceObjective = "Untersucht die Ansammlungen des Kults der Verdammten in Aldur'thar und Mord'rethar.", completion = "Sie müssen etwas planen, aber was, kann ich nicht sagen.\n\nIch werde unsere Späher anweisen, zu beobachten und zu berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62159] = { id = 62159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Schattenlande", description = "Es gibt viel zu tun in den Schattenlanden. Viele Gebiete leiden unter der Animadürre.\n\nEs ist Euch überlassen, wem Ihr als erstes helfen wollt. Wohin werdet Ihr gehen?", sourceObjective = "Wählt, welchen Ort Ihr in den Schattenlanden aufsuchen wollt.", completion = "Dies ist Euer erster Schritt auf dem Weg zum Sieg über den Kerkermeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[62160] = { id = 62160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Strauß Lilien", description = "Dieser Hain braucht etwas Besonderes, etwas, damit er heraussticht.\n\nIch habe einen Plan, aber erst brauche ich Blumen.\n\nNicht irgendwelche Blumen, sondern Nachtlilien. Sie verströmen einen süßen Duft, bei dem man sofort an sternenerleuchtete Nächte auf einem das anmutige Land überblickenden Hügel denken muss.\n\nWenn Ihr den Ardenwald erkundet, sucht an den Wasserläufen nach Nachtlilien und pflückt sie.\nNatürlich werde ich Euch für Eure Mühen entlohnen.", sourceObjective = "Sammelt 10 Nachtlilien.", progress = "Konntet Ihr einige Lilien finden?", completion = "Ah, sie duften herrlich!\n\nEin paar von diesen im Hain verteilt, und die Moral hebt sich wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[62161] = { id = 62161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut aus einem Knochen", description = "Nichts würde ich lieber tun, als sofort nach Revendreth aufzubrechen... aber das scheint mit seinen eigenen Herausforderungen zu kämpfen.\n\nAlle wissen von den Spuren, die wir in der Bastion hinterlassen haben. Die Venthyr werden uns kaum in ihr Reich lassen.\n\nWieder einmal wenden wir uns an Euch. Euer Ruf in den Schattenlanden hat das Vertrauen vieler zurückgewonnen. Jetzt brauchen wir das Vertrauen von Revendreth.", sourceObjective = "Erhöht Euren Ruhm.", completion = "Ihr kommt gerade rechtzeitig. Ich habe ein Schreiben erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62162] = { id = 62162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von der Justiziarin", description = "Justiziarin Treuherz hat persönlich Eure Hilfe angefragt, {name}.\n\nDie frostigen Winde von Eiskrone erwarten Eure Rückkehr.", sourceObjective = "Meldet Euch bei Justiziarin Mariel Treuherz am Argentumturnierplatz in Eiskrone.", completion = "Eure Rückkehr freut mich, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[62163] = { id = 62163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht von der Justiziarin", description = "Justiziarin Treuherz hat persönlich Eure Hilfe angefragt, {name}.\n\nDie frostigen Winde von Eiskrone erwarten Eure Rückkehr.", sourceObjective = "Meldet Euch bei Justiziarin Mariel Treuherz am Argentumturnierplatz in Eiskrone.", completion = "Eure Rückkehr freut mich, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[62165] = { id = 62165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal-Inaras Anliegen", description = "Ihr werdet in der Enklave erwartet.\n\nEs ist an der Zeit, dass Ihr einen Pakt wählt, mit dem Ihr Euch verbündet.", sourceObjective = "Trefft Tal-Inara in der Enklave in Oribos.", sourceObjectiveStatus = "unverified-source-field" }
quests[62166] = { id = 62166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal-Inaras Anliegen", description = "Ihr werdet in der Enklave erwartet.\n\nEs ist an der Zeit, dass Ihr einen Pakt wählt, mit dem Ihr Euch verbündet.", sourceObjective = "Trefft Tal-Inara in der Enklave in Oribos.", sourceObjectiveStatus = "unverified-source-field" }
quests[62168] = { id = 62168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenschriftdepeschen" }
quests[62169] = { id = 62169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen zum Himmel", description = "Das Haus der Augen leidet immer noch unter Akareks Tod. Es sucht nach Führung. Nach einem Ziel.\n\nVielleicht könnt Ihr ihm helfen, es zu finden. Verdient weiter das Vertrauen der Augen. Ihr Geschick wird unbezahlbar für unsere Sache sein.", sourceObjective = "Erhöht Euren Ruhm.", completion = "Das habt Ihr gut gemacht, Schlundgänger. Die Augen vertrauen Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62170] = { id = 62170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid nie allein", description = "<Euer Blick fällt auf ein paar gekritzelte Zeilen. Manche sind unverständlich, andere wohlklingend.>\n\nWie Wind und Regen stürmt der Konflikt in meinem Geist, er wirft sich ruhelos hin und her.\n...\nIch muss die goldenen Himmel finden.\n...\nVergesst es nicht, schreitet voran, mit einem Herzen voller Hoffnung, dann seid Ihr nie allein.\n\n<Ein Aspirant scheint den Weg nach Hause zu suchen. Ihr solltet in der Heldenrast Bescheid geben.>", sourceObjective = "Bringt diese Notizen zum Schankwirt in der Heldenrast.", completion = "Ah, diese weisen Worte stammen gewiss von Eurgon. Ich bin froh, berichten zu können, dass er es nach Hause geschafft hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[62171] = { id = 62171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teekränzchen" }
quests[62172] = { id = 62172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzärmliges Wams", progress = "Ist das ein leicht abgenutztes Wams für mich?", completion = "Ich danke Euch. Ich werde es beiseitelegen, bis die Zeit gekommen ist, um es zu tragen." }
quests[62173] = { id = 62173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langärmliges Wams", progress = "<Euer Gräber greift enthusiastisch nach dem langärmligen Wams.>", completion = "Oooh, es hat Ärmel, die über meine Ellbogen hinausreichen, danke! Ich kann es kaum erwarten, bis wir den richtigen Zeitpunkt finden, es zu tragen." }
quests[62174] = { id = 62174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine anständige Bedeckung", progress = "<Euer Gräberbutler schaut Euch an, als wäre er nicht sicher, ob Ihr ihm die Kappe schenkt oder ihn nur bittet, sie für Euch zu halten.>", completion = "Ist das eine Kappe für mich? Sie ist so biegsam, ich liebe sie! Und sie wird meine Ohren bedecken!" }
quests[62175] = { id = 62175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschick", progress = "Wer ist das? Oh, seht Euch diese wallenden Locken an...", completion = "<Euer Butler dreht den Kopf hin und her, während er sich die fließenden Locken auf dem Porträt vorstellt.>\n\nOh, danke, ich bin sicher, wir werden einen guten Zeitpunkt finden, um meine Haare so zu schneiden!" }
quests[62176] = { id = 62176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Igelfrisur", progress = "Diese Kreatur hat ein unverkennbares Aussehen...", completion = "Ich wette, wenn ich mich damit zu einem Ball zusammenrollen würde, wären die Stacheln ziemlich beängstigend. Nicht, dass ich daran denken würde, so etwas auf einer Party zu tun, es sei denn, es wäre nützlich für uns... Ich werde mir dieses Plakat einfach aufheben, bis die Zeit für diesen Schnitt reif ist." }
quests[62177] = { id = 62177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein denkwürdiger Anblick", progress = "Oh, ich habe diesen Gräber schon einmal gesehen!", completion = "Oh, dieses Aussehen scheint zu einer Rolle wie meiner zu passen, bestimmt haben viele andere Gräber dabei geholfen, indem sie diesen spärlichen, struppigen Stil getragen haben. Ich kann es kaum erwarten, ihn auszuprobieren!" }
quests[62178] = { id = 62178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzer Schlammfarbstoff", progress = "Noch ein Schlammfarbstoff!", completion = "Ah, schwarzer Schlamm, er macht Flecken auf den Fingern, aber er ist sehr vornehm. Ich werde ihn für das nächste Mal aufheben, wenn wir mein Wams färben müssen. Ich möchte Euch daran erinnern, dass wir für jede Färbung einen brauchen werden, aber ich kann diesen hier bereithalten." }
quests[62179] = { id = 62179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blauer Schlammfarbstoff", progress = "Ist Schlamm nicht vielseitig!", completion = "Findet Ihr, dass der blaue Schlamm wie der Himmel aussieht? Dirk war der Meinung, aber ich nicht. Ich werde ihn für das nächste Mal aufheben, wenn wir mein Wams färben müssen. Ich möchte Euch daran erinnern, dass wir für jede Färbung einen brauchen werden, aber ich kann diesen hier bereithalten." }
quests[62180] = { id = 62180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüner Schlammfarbstoff", progress = "Es gibt so viele Schlammfarben, wie kann man nur eine auswählen?", completion = "Ich habe die Schlammlache im Fluchwald nur einmal besucht, aber ich fand sie etwas überfüllt. Ich arbeite definitiv lieber alleine. Ich werde ihn für das nächste Mal aufheben, wenn wir mein Wams färben müssen. Ich möchte Euch daran erinnern, dass wir für jede Färbung einen brauchen werden, aber ich kann diesen hier bereithalten." }
quests[62181] = { id = 62181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubbernder roter Schlammfarbstoff", progress = "Blubbert die noch?", completion = "Oh, er ist immer noch warm. Ich könnte im Glutdistrikt leben. Ich werde ihn für das nächste Mal aufheben, wenn wir mein Wams färben müssen. Ich möchte Euch daran erinnern, dass wir für jede Färbung einen brauchen werden, aber ich kann diesen hier bereithalten." }
quests[62182] = { id = 62182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief von Nadja", description = "Der Brief ist an Nadjas Kontakt Dösbaddel in Dunkelhafen adressiert. Er ist eindeutig mit Nadjas Zeichen versiegelt. Er ist sicher sehr wichtig, und Ihr solltet sicherstellen, dass er ankommt.", sourceObjective = "Bringt den Brief nach Dunkelhafen.\n\nBereitgestellter Gegenstand:", completion = "Ähm, was kann Dösbaddel für Euch tun? Oh, ein Brief... <Dösbaddel sieht Nadjas Siegel, und seine Augen werden groß.> Ja, habt Dank. Ich habe auf diesen Brief gewartet. Er ist von meiner Tante. <Dösbaddel zwinkert Euch zu.> Sie war krank. Ich werde allen erzählen, dass Ihr geholfen habt, wichtige Briefe zu überbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[62183] = { id = 62183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein tropfendes Paket verderblicher Ware", description = "Ein sehr genauer Jemand wollte, dass dieses Paket Ta'tru auf dem Nachtmarkt erreicht. Sieht wie Mittlerschrift aus. Das Paket tropft offenkundig und ist als verderblich gekennzeichnet. Es wäre sicher besser, es schnell zuzustellen.", sourceObjective = "Bringt das Paket zum Nachtmarkt.\n\nBereitgestellter Gegenstand:", completion = "Ooh, das ist mein Paket mit fleischfressendem Schleim?! Hoffentlich habt Ihr nichts davon an die Finger bekommen. Beim Tragen von Handschuhen im Umgang mit diesem besonderen Schleim besteht nur eine fünfundzwanzigprozentige Wahrscheinlichkeit, schädliche Nebenwirkungen zu erleiden. Die Handschuhe sollte man verbrennen, aber das überlasse ich Euch. Ich werde den Leuten hier von Eurer Hilfe bei der Zustellung berichten, auch wenn sie zu spät war.", sourceObjectiveStatus = "unverified-source-field" }
quests[62184] = { id = 62184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kiste mit Sinvyrerz", description = "Die Kiste ist ziemlich groß und sieht schwer aus. Sieht aber auch nach etwas aus, für das man entlohnt wird. Bringt die Kiste zu Gibbo am Alten Tor. Er sollte regelmäßige Lieferungen erwarten.", sourceObjective = "Bringt die Kiste zum Alten Tor.\n\nBereitgestellter Gegenstand:", completion = "Endlich! Was habt Ihr mit der Lieferung angestellt? Ihr seid eine Woche zu spät, und jetzt hinke ich hinterher. <Er bemerkt, dass Ihr etwas sagen wollt, und redet weiter.> Nein, ich will es gar nicht hören. Dafür bekommt Ihr keine gute Bewertung, aber hier ist Euer vereinbarter Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[62185] = { id = 62185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um Aufmerksamkeit", description = "Ein wachsames Auge auf den Kult der Verdammten zu haben, hat sich als herausfordernd... und gefährlich erwiesen.\n\nViele unserer Hippogryphenreiter sind kürzlich mit den geflügelten Schrecken des Kultes in Konflikt geraten. Obwohl einige wenige entkommen konnten, wurden die anderen gefangen genommen und nach Aldur'thar gebracht.\n\nTut, was Ihr könnt, um sie von ihren Entführern zu befreien. Wir können es uns nicht leisten, noch mehr unserer Streitkräfte zu verlieren.", sourceObjective = "Befreit 5 Argentumhippogryphenreiter aus Aldur'thar.", completion = "Ich schulde Euch meinen Dank.\n\nIch versichere Euch, dies wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62186] = { id = 62186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgequollener Animasamen", description = "Die maskierten Sylvar legen einen einzelnen mit Anima gefüllten Samen ab. Ihr könnt nur raten, zu welchem Zweck. Dromanin Tashmur wüsste die Rückgabe einer solch wertvollen Ressource zu schätzen.", sourceObjective = "Bringt den aufgequollenen Animasamen zu Dromanin Tashmur in Tirna Vaal.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr mir mitgebracht? Warum sollten die Maskierten so Anima sammeln? Eine Sorge für die Zukunft. Danke, dass Ihr mir dies gebracht habt. Er wird viele Wildsamen nähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[62187] = { id = 62187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säckchen Culexholz", description = "Dieses verlorene Säckchen enthält Holz der Culexbäume in der Nähe. Flatterfang würde zu schätzen wissen, es zurückzubekommen.", sourceObjective = "Bringt das Säckchen Culexholz zu Flatterfang an den Ufern des Lebens.\n\nBereitgestellter Gegenstand:", completion = "Ein ganzes Säckchen voll?! Wunderbar! Damit kann ich einiges ausrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62188] = { id = 62188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt einen Stern", description = "Ich brauche Eure Hilfe in einer... heiklen Angelegenheit, {name}.\n\nSternfliegenschwingen sind eine wichtige Zutat einiger unserer Kreationen, und unsere Vorräte sind erschöpft.\nKleine Dinger, sehr zerbrechlich, und ich kann sie nicht vorsichtig genug behandeln.\n\nKönntet Ihr Sternfliegen für mich besorgen? Sie müssen lebend gefangen werden, damit ihre Schwingen nicht verderben, und wir brauchen sie wirklich dringend. \n\nIch werde natürlich sicherstellen, dass Ihr für Eure Mühen entlohnt werdet.", sourceObjective = "Sammelt 13 schillernde Sternfliegen.", completion = "Unglaublich! Ich konnte Euer Bündel schon leuchten sehen, bevor Ihr eingetroffen seid.\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[62189] = { id = 62189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschirmbestandteile", description = "Feine Stoffbahnen, hölzerne Sonnenschirmstreben, Holzdübel und Metallklammern: alles, was es für den Bau neuer Sonnenschirme braucht. Die sind im Glutdistrikt viel Gold wert. Mats würde Euch sicher reich entlohnen, wenn Ihr ihm diesen Schatz bringt.", sourceObjective = "Bringt die Komponenten zum Refugium des Wahnsinnigen.\n\nBereitgestellter Gegenstand:", completion = "Oh wow, was für ein Fund! Hier, ein Haufen durchflutete Rubine für das Bündel. Die Besten des Glutdistrikts. Und wenn Euch etwas von meinen Waren gefällt, lasst es mich wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62190] = { id = 62190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echte Drecksarbeit", description = "Wir müssen die Schlammlache hinbekommen, bevor wir Euren Gräberbutler machen.\n\nSieht aus, als hätte die Animaknappheit der Lache jede Menge Probleme gemacht.\n\nSchlammlachen brauchen jede Menge Dreck und Fasern, damit gute Gräber draus werden.\n\nAber mit all den Verschlingern und fiesen Elementaren, die sich in diesem ganzen wilden Schlamm bilden, komme ich nicht nahe genug ran, um ihn zu füttern!\n\nHelft mir und werft etwas schmutzigen Schutt in die Lache, ja?", sourceObjective = "Werft 6 Teile schmutzigen Schutt in die Schlammlache.", completion = "Ich kann es von hier aus riechen.\n\n<Rendel atmet tief ein und seufzt.>\n\nTrautes Heim.", sourceObjectiveStatus = "unverified-source-field" }
quests[62194] = { id = 62194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Kampfes", description = "In den Schattenlanden gibt es so viel Magie zu lernen!\n\nEine Bedrohung der Bastion gefährdet viele ihrer uralten Lehren. Ich möchte ihre Schriftrollen studieren, bevor sie für immer verloren sind. Wir müssen dort hinreisen und retten, was wir können!\n\nHelft mir, die Verschmähten im Tempel der Demut zurückzuschlagen und die Schriftrollen darin zu retten.", sourceObjective = "Helft Sabrina, 8 uralte Lehren zu sammeln und 8 Gegner der Verschmähten zu eliminieren.", completion = "Ihr habt uns geholfen, unsere Truppen zu stärken, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62195] = { id = 62195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Wort", description = "Inquisitorin Darksion war eine aufstrebende Meisterin der arkanen Künste, bevor Denathrius sie eingesperrt hat.\n\nIch habe gehört, dass sie ihr Wissen mit jedem teilen will, der sie aus ihrem Gefängnis befreit.\n\nIch möchte alles erfahren, was sie weiß! Wir müssen sie befreien!", sourceObjective = "Helft Sabrina, Inquisitorin Darksion zu befreien.", progress = "Haben wir etwas Gutes gefunden?", completion = "Ihr habt uns geholfen, unsere Truppen zu stärken, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62200] = { id = 62200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funktionsfähiger Animakern", description = "<Der unergründliche Kern surrt in einem zufriedenen Ton.\n\nDafür hat sicherlich jemand Verwendung?>", sourceObjective = "Bringt den funktionsfähigen Animakern zu Kalisthene.", completion = "Danke dafür, {name}. Wir müssen so viel Anima bewahren, wie wir können.", sourceObjectiveStatus = "unverified-source-field" }
quests[62203] = { id = 62203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signifikante Spiegelstörungen" }
quests[62204] = { id = 62204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signifikante Spiegelstörungen" }
quests[62205] = { id = 62205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyretikette", progress = "Ist das Theotars neues Buch?", completion = "Wisst Ihr, ich mag diesen Theotar wirklich. Er kennt sich aus und ist nett zu uns, auch wenn er manchmal annimmt, dass wir Gedanken lesen können. Dummer Venthyr." }
quests[62206] = { id = 62206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenwaldetikette", sourceObjective = "Dieses hier sieht lustig aus, ich lese gerne über Träume, und es hat Bilder!", sourceObjectiveStatus = "unverified-source-field" }
quests[62207] = { id = 62207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastionsetikette", progress = "Sieht aus wie ein 'großes' Buch.", completion = "Das scheint ziemlich streng zu sein. Ich bin überrascht, dass sie zu Partys kommen, ich glaube, hier steht, dass das vielleicht nicht erlaubt ist. Nun, ich werde dafür sorgen, dass ich es mir Wort für Wort einpräge, ich bin sicher, das haben sie bereits getan." }
quests[62208] = { id = 62208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxi-Etikette", progress = "Sieht kürzer aus als die anderen, aber... sind das Patronen?", completion = "Ich will nicht lügen, das klingt wirklich trocken. Darf ich wenigstens ihre coole Rüstung tragen?" }
quests[62209] = { id = 62209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundemeister Vasanok" }
quests[62210] = { id = 62210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanngror der Folterer" }
quests[62211] = { id = 62211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huschende Brutmutter" }
quests[62213] = { id = 62213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mittlergeschäft", description = "Hallo {name}. Ich bin auf eine lukrative Geschäftsidee gestoßen, die mir... uns... sehr helfen wird! Au'narim würde uns Vorräte geben, wenn wir ihm helfen, einen Handel zu retten, der schiefgegangen ist.\n\nAnscheinend sind mehrere seiner Leute nie von einem Auftrag zurückgekehrt. Wir sollen ihrem Weg folgen und den Gegenstand holen, den sie nicht zustellen konnten. Einfach, oder?\n\nDamit uns nichts zustößt, habe ich einige Gegenstände besorgt, die uns helfen könnten.\n\nSeid Ihr dabei?", sourceObjective = "Findet die Mittlerkugel.", progress = "Habt Ihr den fraglichen Gegenstand gefunden?", completion = "Ich wusste, der Schlundgänger würde das hinbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62214] = { id = 62214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen der Verdammnis", description = "Wenn wir überleben wollen, müssen wir unsere Feinde in Schach halten.\n\nDer Gorgoa tritt über seine Ufer, und die Schlundgebundenen werden stärker.\n\nDie Verdammnisfestung wurde mit neuen Truppen verstärkt. Wir können nicht zulassen, dass die Schlundgebundenen ihre Reihen weiter ausbauen.\n\nVerschafft Euch Zugang zur Verdammnisfestung und dünnt ihre Streitkräfte aus. Wenn Ihr das erledigt habt, könnt Ihr Euch Eure Belohnung bei mir abholen.", sourceObjective = "Tötet Truppen der Schlundgebundenen in der Verdammnisfestung im Schlund.\n\nEmpfohlene Spieleranzahl [3]", completion = "Ein kleiner Sieg, Schlundgänger. Viele mehr werden vonnöten sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62216] = { id = 62216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildungsprogramm", description = "Unteroffizier Krashj ist ein zuverlässiger Ausbilder, aber diese Rekruten brauchen eine anständige Trainingseinheit mit einem echten Krieger. Mit jemandem, der sich auf dem Schlachtfeld die Hände blutig gemacht hat. Mit jemandem wie mir!\n\nUnd ich kenne einen Kampf, der die Truppen auf Vordermann bringen wird.\n\nBringen wir ihnen ein paar Dinge bei.", sourceObjective = "Tötet Rottius.", completion = "Ihr beide gebt ein tolles Team ab. Es ist gut, zwei verlässliche Waffenbrüder zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[62217] = { id = 62217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Ausbildung", description = "Obwohl nicht durch uns, hat Maldraxxus den Kyrianern der Bastion großes Unrecht getan. Wir müssen alles tun, was in unserer Macht steht, um das wiedergutzumachen.\n\nDie Bedrohung durch die Verschmähten ist weiterhin ein Dorn in ihrem Fleisch. Klingt nach einer perfekten Gelegenheit, um unsere Unterstützung zu zeigen und unseren Rekruten etwas Kampferfahrung zu bieten.", sourceObjective = "Tötet 15 Streitkräfte der Verschmähten in der Ewigen Schmiede in der Bastion.", completion = "Ihr und Marz arbeitet gut zusammen. Er fängt alles ab, wenn man es braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62218] = { id = 62218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brunnen für die Fae", description = "Nuuminuuru bringt ihre Tage damit zu, die vielen Feen des Ardenwalds zu umsorgen und zu beschützen. Sie hat ihre Sorgen um einige der ihr anvertrauten Feen zum Ausdruck gebracht, die sie seit Längerem nicht gesehen hat.\n\nMeldet Euch bei Nuuminuuru und findet heraus, ob Ihr bei der Suche nach ihren versprengten Waldgeistern helfen könnt.", sourceObjective = "Meldet Euch bei Nuuminuuru im Schimmerkaskadenbecken im Ardenwald.", progress = "Seid gegrüßt, Verbündeter der Seelenbringer.", completion = "Ein Feenbrunnen als willkommene Entspannung... ein fürwahr attraktiver Anreiz.", sourceObjectiveStatus = "unverified-source-field" }
quests[62219] = { id = 62219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fantastische Ablenkungen", description = "Meine Feenfreunde flitzen vielfach Wolkenschlössern nach und sind ein seltener Anblick.\n\nAbgelenkt vom rechten Pfad führt ihre launenhafte Art sie oftmals auf Irrwege.\n\nFindet meine Freunde, besteht auf ihrer Rückkehr zu meinen Wurzeln, und sowohl Euch als auch ihnen winkt eine Belohnung.", sourceObjective = "Findet Flussblüte, Mondwind und Flitterflügel und überzeugt sie, zu Nuuminuuru zurückzukehren.", progress = "Meine Schutzbefohlenen kehren immer an meinen Sitz zurück, um Geschichten von ihren Abenteuern zu erzählen und ihren Geist zu stärken.\n\nJe länger sie fortbleiben, umso tiefer meine Sorge um sie.", completion = "Das Wasser Eures Reiches erfrischt meine Schutzbefohlenen auf eine Weise, die unser Zuhause nicht bieten kann.\n\nSie kehren wieder zurück, um sich auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62221] = { id = 62221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein eigenes Todespony!", progress = "Das ist so ein schönes Todespony. Seit ich mein erstes gesehen habe, träume ich davon...", completion = "<Euer Butler weint fast.>\n\nIch bekomme mein eigenes Todespony zum Reiten? Ihr seid der beste Sterbliche, dem ich je begegnet bin!" }
quests[62222] = { id = 62222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf silbernen Schwingen", progress = "Was soll ich mit dem Ding machen?", completion = "<Euer Butler steht unter Schock, nachdem Ihr ihm gesagt habt, dass er fliegen wird.>\n\nWenn Ihr wirklich wollt, dass ich Euch in der Luft folge... natürlich werde ich das tun... bitte nicht zu hoch..." }
quests[62223] = { id = 62223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufung des Aufstiegs: Mikanikos", description = "<Diese Schriftrolle ähnelt Kleias Einladung zum Pfad des Aufstiegs, doch die Handschrift gehört eindeutig Sika.\n\nSie ist an Mikanikos gerichtet und lädt ihn gemeinsam mit Bron zur Teilnahme am Pfad ein.\n\nVielleicht solltet Ihr sie zu Mikanikos bringen.>", sourceObjective = "Informiert Mikanikos, dass er jetzt am Pfad des Aufstiegs teilnehmen kann.", completion = "Ich? Am Pfad des Aufstiegs teilnehmen? Überrascht mich!\n\nNatürlich sind Bron und ich dabei. Die Fortschritte, die wir bei der Zenturionenentwicklung machen können... Stellt Euch bloß vor!", sourceObjectiveStatus = "unverified-source-field" }
quests[62224] = { id = 62224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Faden der Hoffnung", description = "Der Hof der Nacht ist wie eine durstige Blume, die ihre Nährstoffe gierig aufsaugt. Wenn sie gut versorgt wird, blüht sie, doch wenn es ihr an Nahrung mangelt, verkümmert sie.\n\nUnsere Wurzeln trocknen aus, wir brauchen mehr Anima!\n\nIch habe Arbeiter losgeschickt, um seidenüberzogene Fänger entlang der Straßen und Wege durch den Ardenwald zu platzieren. Sie werden eine winzige Menge Anima einfangen. Nicht viel, aber genug für unsere Bedürfnisse.\n\nFindet sie und bringt die animaversetzte Seide zurück.", sourceObjective = "Sammelt 13 Stücke animaversetzte Seide.", progress = "Habt Ihr die Seide gefunden?", completion = "Gut gemacht. Unsere Blätter heben sich dankbar in den Himmel.", sourceObjectiveStatus = "unverified-source-field" }
quests[62225] = { id = 62225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Platzende Blasen", description = "<Die Worte der schattenhaften Heroldin sind dunkel und ahnungsvoll. Was immer der \"Verbannte\" zu erreichen gedenkt, es darf nicht geschehen.\n\nIn den Kesseln in der Nähe brodelt etwas. Nach der Sorgfalt zu urteilen, mit der die Kultisten sich um sie kümmern, muss ihr Inhalt entscheidend für ihre Pläne sein.\n\nEinige Fässer mit einer scheinbar neuartigen Seuche sind unbeaufsichtigt geblieben. Vielleicht können sie als Instrumente zur Sabotage dienen.>", sourceObjective = "Sabotiert 3 Experimente des Kults der Verdammten in Mord'rethar.", completion = "Dem Licht sei Dank, Ihr seid unversehrt zurückgekehrt!\n\nKonntet Ihr etwas darüber in Erfahrung bringen, was der Kult treibt?", sourceObjectiveStatus = "unverified-source-field" }
quests[62226] = { id = 62226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talethis Verlangen" }
quests[62227] = { id = 62227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xertoras Konstrukt" }
quests[62229] = { id = 62229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashrakas Informationen" }
quests[62231] = { id = 62231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velkeins Klinge" }
quests[62232] = { id = 62232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweigte Taktik", description = "Die Spriggans aus dem Ardenwald waren schon immer ein Ärgernis. Aber unter Mueh'zalas Einfluss könnten sie zu einer Bedrohung für die gesamten Schattenlande heranwachsen.\n\nLassen wir die Truppen gegen einen richtigen Gegner antreten.", sourceObjective = "Tötet 12 Borstenzapfenspriggans im Nebelschleierdickicht im Ardenwald.", completion = "Ich sehe, dass Ihr und Marz fleißig wart. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62234] = { id = 62234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Kolosses", description = "Ich habe noch eine Aufgabe für Euch, <Schlundgänger/Schlundgängerin>.\n\nTief in der Verdammnisfestung lauert eine mechanische Bedrohung, die als Seelenstahlkoloss bekannt ist. Wir müssen sie zerstören, bevor sie Chaos und Verwüstung bringt.\n\nReist zur Festung und dann über die Brücke und zum Altar der Herrschaft. Dort findet Ihr den Seelenstahlkoloss, der seinen riesigen Schatten über den Schlund wirft.\n\nZerschmettert den Koloss und bringt mir seine Kraftquelle als Beweis Eures Triumphs.", sourceObjective = "Beschafft einen kolossalen Energiekern aus der Verdammnisfestung im Schlund.\n\nEmpfohlene Spieleranzahl [3]", progress = "Die Kraftquelle... sie war doch nicht zu schwer, oder?", completion = "Die in dem Energiekern gefangenen Seelen können vielleicht noch gerettet werden. Lasst mich jetzt bitte weiter forschen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62235] = { id = 62235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstreut ihre Ängste" }
quests[62236] = { id = 62236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasselbeutels verschwundene Rüstung" }
quests[62237] = { id = 62237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöser Seelenspiegel", description = "<Ein schimmernder Seelenspiegel lenkt Eure Aufmerksamkeit auf Devos' Leiche.\n\nMerkwürdig, dass sie einen bei sich hatte. Vielleicht sollte Thenios einen Blick darauf werfen.>", sourceObjective = "Bringt den mysteriösen Seelenspiegel zu Thenios im Tempel im Äonischen Archiv.", progress = "Wie kann ich behilflich sein?", completion = "<Thenios untersucht den Spiegel genau.>\n\nIch verstehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62238] = { id = 62238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlgeleitete Seele", description = "Uther war ein Verfechter der Gerechtigkeit in Eurer Welt. Ihr seid sicher überrascht, dass er hier einem Anführer folgt, der alles verkörpert, wogegen er im Leben gekämpft hat.\n\nIch glaube, Ihr solltet seine Erinnerung selbst sehen. Bringt sie zu meinem Seelenspiegel. Betrachtet die Erinnerungen darin.", sourceObjective = "Benutzt den Seelenspiegel im Äonischen Archiv, um Euch Uthers Ankunft in der Bastion anzusehen.", progress = "Manchmal ist es die bittere Wahrheit, die am dringendsten erkannt werden muss.", completion = "Hoffentlich hilft Euch diese Erinnerung, Uthers Pfad zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62239] = { id = 62239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagerbekämpfung", description = "<Die Waffe summt mit einer dunklen, statischen Energie. Was auch immer dieser Schlundgebundene untersucht haben mag, es hatte wohl Erfolg bei den Nagetieren in der Nähe.\n\nEine nähere Untersuchung könnte weitere Informationen ans Licht bringen.>", sourceObjective = "Testet die Rute des Peinigers an 8 Riesenschlundratten im Bestienlabyrinth aus.", completion = "Geschieht ihnen recht, wenn sie es unbeaufsichtigt gelassen haben.\n\nIch bin mir sicher, wir finden einen anderen Zweck dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[62241] = { id = 62241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trainingsabläufe" }
quests[62244] = { id = 62244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgraben", description = "Die dünnen, bleichen Gestalten von Revendreth haben Anima gehortet.\n\nIch habe gehört, dass sie sie verstecken. Sie haben Löcher in den Wäldern gegraben und sie einfach dort gelassen, damit jeder vorbeikommen und sie mitnehmen kann.\n\nIch sage, dass wir das sein werden!\n\nHolen wir uns etwas Anima.", sourceObjective = "Sammelt 15 verlorene Animabehälter.", completion = "Danke für die Vorräte. Ich werde Euch regelmäßig welche zur Seite legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62245] = { id = 62245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62246] = { id = 62246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gefallene Freundin", description = "Ein Armreif, der zart mit lebendigen Ranken verwebt ist, fällt von Vivannas Handgelenk, als sie getötet wird. In den Ranken steht geschrieben: \n\n\"Bis zum Ende des Winters.\n\n-Flwngyrr\"", sourceObjective = "Bringt diesen Armreif zu Flwngyrr im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "<Er nimmt den Armreif aus Eurer Hand. Ein Moment vergeht, bevor er wieder spricht.>\n\nIhr Lieblingstee war Azurblüte.\n\nDanke, dass Ihr mir das gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62248] = { id = 62248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62249] = { id = 62249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62250] = { id = 62250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Abenteuer wartet", description = "{name}! Ihr werdet in der Gegenwart benötigt. Die Dinge haben sich... Nun, kommt am besten einfach zurück und seht selbst.\n\nIch an Eurer Stelle würde erledigen, was zu erledigen ist, und dann zurückkommen. Ich kann Euch nicht viel länger in der Vergangenheit bleiben lassen!", sourceObjective = "Kehrt nach Sturmwind zurück, um ein neues Abenteuer anzugehen. Chromies Magie endet, wenn Ihr Stufe 70 erreicht. Dann kehrt Ihr nach Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62256] = { id = 62256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertextraktion", description = "Oh, <mein guter Freund/meine liebe Freundin> {name}! Hört mal, ich stecke ein bisschen in der Klemme. Ich möchte gerade mit dem Mittler Au'larrynar etwas aushandeln, aber er will einen Auftrag erledigt haben, bevor er einwilligt.\n\nEr hatte einen Geschäftspartner, der mit einem seltenen Gegenstand verschwunden ist. Er will, dass ich... wir... seinen Besitz finden und zurückbringen.\n\nSein Geschäftspartner wurde zuletzt im Ardenwald gesichtet. Ich weiß, ein seltsamer Ort, viel zu hell für mich. Aber ich... wir... müssen diesen Handel wirklich abschließen!\n\nUnd, seid Ihr bereit?", sourceObjective = "Reist zum Ardenwald, findet Tabithia und bringt das andersweltliche Ei zurück.", progress = "Ich gehe davon aus, dass Ihr Euren Teil des Vertrags erfüllt habt?", completion = "Ah, wie herrlich. Euer rekonstruierter Freund meinte, Ihr würdet es erledigen, und das habt Ihr auf beeindruckende Weise!\n\nLasst ihn wissen, dass ich dies als Anzahlung auf seine Schulden verbuche.", sourceObjectiveStatus = "unverified-source-field" }
quests[62258] = { id = 62258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel über der Bastion" }
quests[62259] = { id = 62259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaerfüllter Traumfänger", description = "Ihr stolpert über einen verzauberten Traumfänger, der so abgelegen liegt, dass er eine große Menge Anima sammeln konnte, ohne geerntet zu werden. Dromanin Morgenblüte im nahe gelegenen Traumsang Fenn hätte ihn sicher gerne zurück.", sourceObjective = "Bringt den verzauberten Traumfänger zu Dromanin Morgenblüte in Traumsang Fenn.\n\nBereitgestellter Gegenstand:", completion = "Herrje! Wie ist der denn da hingekommen? Egal. Diese Anima wird viele Seelen nähren. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[62261] = { id = 62261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleifer", description = "Es ist gar nicht leicht, meine Hände für den Kampf messerscharf zu halten. Bei all dem Gehacke und Gespalte von Schädeln werden sie ganz schnell stumpf! Was soll ein Mädchen da tun?\n\nDas Haus der Auserwählten stellt Wetzsteine von höchster Qualität her. Ich bezweifle, dass sie die freiwillig herausrücken, aber meine Klingen können sie bestimmt überreden.\n\nWollen wir beide ihnen nicht einen Besuch abstatten und sehen, wie viele sie entbehren können?", sourceObjective = "Sammelt 12 Wetzsteine und 3 knochengeschorene Schleifer.", progress = "Habt Ihr sie alle getötet?", completion = "Ich sehe, dass Guillotines 'Verhandlungen' erfolgreich waren.\n\nDanke, Schlundgänger. Diese Wetzsteine werden nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62262] = { id = 62262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzfütterung", description = "Gerade, als ich bei unserer alternativen Verteidigungsforschung Fortschritte gemacht habe, sind mir die Sporenproben ausgegangen!\n\nDie Pilze, die ich verwende, findet man nur an einem ausgemacht unangenehmen Ort im Südosten. Um ein paar Proben in geeigneter Größe ernten zu können, muss man sie... wie soll ich sagen... füttern.\n\nFragt nicht warum, aber sie scheinen am schnellsten zu wachsen, wenn sich in ihrer Nähe ein schöner, verrottender Leichnam befindet.\n\nVersucht, ein paar Untote in die Nähe unserer Pilzfreunde zu locken. Dadurch erhalten sie alle Nährstoffe, die sie brauchen, um groß und stark zu werden.", sourceObjective = "Sammelt 20 reife Sporenproben von Düsternispilzen in Geißelholme.", progress = "Wie läuft's mit den Proben?", completion = "Oh, die sind superb!\n\nIch hoffe, Ihr habt Euch die Hände nicht allzu schmutzig machen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62263] = { id = 62263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung in einer Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", completion = "Es muss schön sein, die Zeit zu haben, einfach nur dazusitzen und nachzudenken.\n\nIch selbst habe kaum Zeit. Diesen Ort in Schuss zu halten, ist eine Menge Arbeit!\n\nEs war jedenfalls sehr nett von Euch, der alten Schildkröte zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62265] = { id = 62265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Abenteuer wartet", description = "{name}! Ihr werdet in der Gegenwart benötigt. Die Dinge haben sich... Nun, kommt am besten einfach zurück und seht selbst.\n\nIch an Eurer Stelle würde erledigen, was zu erledigen ist, und dann zurückkommen. Ich kann Euch nicht viel länger in der Vergangenheit bleiben lassen!", sourceObjective = "Kehrt nach Orgrimmar zurück, um ein neues Abenteuer anzugehen. Chromies Magie endet, wenn Ihr Stufe 70 erreicht. Dann kehrt Ihr nach Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[62275] = { id = 62275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastion", description = "Nach einem Überraschungsangriff durch die maldraxxischen Truppen und einer Armee ihrer gefallenen Brüder namens \"Die Verschmähten\" drohen die Aufgestiegenen, die Kontrolle über die Bastion zu verlieren, wenn ihnen keiner zur Hilfe eilt.", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Die Bastion braucht dringend Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62276] = { id = 62276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Toten anstoßen", description = "Die Verschmähten verwüsten die Tempel der Bastion, und die Aspiranten fliehen und lassen ihre Vorräte zurück.\n\nDie ganzen herrlichen Nektarflaschen in den Händen der Verschmähten? Wohl kaum! \n\nWir können nicht alle Aspiranten retten, aber wir können die Verschmähten davon abhalten, sich die Vorräte zu nehmen. Außerdem... haben wir hier nichts zu trinken.", sourceObjective = "24 geläuterten Nektar und 2 Provosten gesammelt", progress = "Habt Ihr Vorräte für uns gefunden?", completion = "Äh, ich sehe, Ihr habt ein paar Freunde mitgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[62277] = { id = 62277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenwald", description = "Der Ardenwald wird weiter von den Drust und anderen schändlichen Kräften bedroht.\n\nDie Winterkönigin könnte Eure Hilfe im Kampf gegen die gebrauchen, die den Ardenwald vernichten wollen.", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Der Ardenwald würde Eure Hilfe sehr zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62278] = { id = 62278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxus", description = "Wo nun die Häuser in Trümmern liegen, ringt die treue Armee des Primus darum, ihre Stellung in Maldraxxus zu halten.\n\nSie ist auf Hilfe angewiesen, um das Blatt zu ihren Gunsten zu wenden.", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Die treu dem Primus dienenden Armeen brauchen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62279] = { id = 62279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revendreth", description = "Der Verrat durch Graf Denathrius stürzte Revendreth ins Chaos. \n\nEure Unterstützung wird dringend benötigt!", sourceObjective = "Sprecht mit Tal-Inara.", completion = "Revendreth wäre für Euren Beistand überaus dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[62280] = { id = 62280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Limbus" }
quests[62284] = { id = 62284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfobservation", description = "Es ist offensichtlich, dass Ihr Sterblichen bei Konflikten aufblüht. Die Mitglieder meines Kartells haben ein reges Interesse daran, Euer Kampfkönnen in Aktion zu erleben.\n\nIhr scheint gern um umstrittenes Terrain zu kämpfen. Die Beobachtung eines solchen Territorialverhaltens wäre für mich von Vorteil und könnte auch für Euch eine Chance sein.\n\nKann ich mit Eurer Teilnahme rechnen?", sourceObjective = "Verdient Ehre auf zufälligen Schlachtfeldern.", completion = "Ausgezeichnet. Ihr kämpft erbittert, um ein Stück Land zu beanspruchen. Der Beobachter wird das faszinierend finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62285] = { id = 62285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsobservation", description = "Euer Konflikthunger ist ein Thema, über das hier in Oribos viel diskutiert wird, <Sterblicher/Sterbliche>. Die Mitglieder meines Kartells haben ein reges Interesse daran, Euer Kampfkönnen in Aktion zu erleben.\n\nObwohl ich weiß, dass vor Kurzem ein großer Krieg auf Eurer Welt zu Ende gegangen ist, höre ich, dass an bestimmten Orten weiterhin große Konflikte ausgetragen werden.\n\nWäre es möglich, eine Vorführung zu arrangieren?", sourceObjective = "Verdient Ehre auf epischen Schlachtfeldern.", completion = "Ein äußerst erhellender Konflikt. Der Beobachter wird erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62286] = { id = 62286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplänkelobservation", description = "Erstaunlich, wie viel Unterhaltung Eure Art aus dem Konflikt zieht, <Sterblicher/Sterbliche>. Die Mitglieder meines Kartells haben ein reges Interesse daran, Euer Kampfkönnen in Aktion zu erleben.\n\nEs heißt, in Geplänkeln stellen Eure größten Champions ihre kämpferische Überlegenheit über die Konkurrenten zur Schau. Ohne Zweifel könnte mein Volk durch Beobachtung eines solchen Wettstreits lernen.\n\nErweist Ihr mir die Ehre einer Demonstration?", sourceObjective = "Verdient Ehre in Arenageplänkeln.", completion = "Faszinierend. Äußerst faszinierend. Der Beobachter wird erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62287] = { id = 62287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arenaobservation", description = "Die Einwohner Eurer Welt erblühen im Konflikt, <Sterblicher/Sterbliche>. Die Mitglieder meines Kartells haben ein reges Interesse daran, Euer Kampfkönnen in Aktion zu erleben.\n\nGeplänkel in eingeschränkter Umgebung könnten sich als lehrreich für mich und lukrativ für Euch erweisen.\n\nWas meint Ihr?", sourceObjective = "Verdient Ehre in Arenen.", completion = "Eine erfolgreich getroffene Vereinbarung ist für mich ein Grund zur Freude! Der Beobachter wird erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62288] = { id = 62288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamworkobservation", description = "Es ist wahrlich faszinierend, wie Eure Art im Konflikt erblüht, <Sterblicher/Sterbliche>. Die Mitglieder meines Kartells haben ein reges Interesse daran, Euer Kampfkönnen in Aktion zu erleben.\n\nEs heißt, manche Eurer kriegerischen Demonstrationen werden von festgelegten Teams vollführt. Mein Volk ist mit solchen Wettkämpfen nicht vertraut.\n\nWärt Ihr bereit, mir eine Demonstration zu bieten?", sourceObjective = "Verdient Ehre auf gewerteten Schlachtfeldern.", completion = "Unsere Vereinbarung hat mir einige äußerst nützliche Informationen beschert. Der Beobachter wird erfreut sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62291] = { id = 62291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62292] = { id = 62292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pechschwarze Geißelsteine", progress = "Die Mächtigsten der Untoten tragen Geißelsteine bei sich, die mit der dunkelsten Magie durchtränkt sind.\n\nWir wissen nicht, woher sie kamen, aber sie verfügen über eine Macht, die ihresgleichen sucht.\n\nBitte übergebt alle, die ihr findet, dem Argentumkreuzzug. Wer weiß, was für ein Übel in ihnen lauert?", completion = "Wir werden diese Steine sofort untersuchen und sie wegschließen. Sie bereiten mir Unbehagen." }
quests[62293] = { id = 62293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdunkelte Geißelsteine", progress = "Geißelsteine waren einst unter den Dienern des Lichkönigs weit verbreitet. Doch diese neuen sind anders... und dunkler.\n\nBringt sie uns, wenn Ihr sie findet. Sie werden sowohl ein Zeichen Eurer Siege sein, als auch eine Gelegenheit für uns, ihre seltsame Magie zu studieren.", completion = "Wir haben uns schon einmal gegen die Untoten durchgesetzt, und wir werden es wieder tun! Für das Licht!" }
quests[62294] = { id = 62294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Lichs Müll...", description = "Man sagt nicht umsonst, des einen Müll ist des anderen Schatz, und auf Relikte trifft das ganz besonders zu.\n\nDas Haus der Rituale ist äußerst verschwiegen, weswegen jede Information, die wir über sie herausbekommen, umso wertvoller sein wird.\n\nIch bin sicher, dass wir in ihrem Abfall viele nützliche Dinge finden können.", sourceObjective = "Durchsucht die Trümmerhaufen im Haus der Rituale nach Hinweisen auf seine Vergangenheit und findet ein faszinierendes uraltes Relikt.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Einfach fantastisch! Es wird uns nützliche Einblicke in die Geschichte der Markgräfin Sin'dane liefern... vielleicht auch Informationen, die wir später brauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[62296] = { id = 62296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Unbekannte", description = "Kommt Ihr den alten Marasmius besuchen? Ich habe eine ganz besondere Aufgabe für Euch.\n\nEiner meiner Sprösslinge hat einen merkwürdigen Ort gefunden, einen Ort, den ich noch nie zuvor gesehen habe.\n\nIch bin nicht ganz sicher, was sich darin befindet oder ob es gefährlich ist. Aber dafür habe ich ja meine verlässlichen Pilzomanten!\n\nWas sagt Ihr, {name}? Bereit für ein Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Bleibt wachsam. Wir wissen nicht, wo das hinführt!", completion = "Das war knapp. Dieses Ungeziefer bringt ganze Teile des Ardenwalds zur Explosion, wenn wir nicht aufpassen. Wir haben sowieso schon genug Probleme!", sourceObjectiveStatus = "unverified-source-field" }
quests[62297] = { id = 62297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fataler Fehler", description = "<Akolyth/Akolythin>, wir könnten hier Hilfe gebrauchen!\n\nAnscheinend hat einer Eurer Mitschüler das Ritual spektakulär vermasselt. Jetzt fließen nekromantische Energien unkontrolliert durch das Haus.\n\nDiese Bedrohung muss beendet werden. Könnt Ihr dabei helfen?", sourceObjective = "Tötet 7 fatale Vereinigungen im Haus der Rituale.", completion = "Gut gemacht, Akolyth. Der Rest sollte sich mit der Zeit auflösen.\n\nHier, nehmt das. Das stammt von dem Unglücksraben, der dieses Chaos verursacht hat. Ich hoffe, Ihr könnt damit besser umgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62298] = { id = 62298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic 20-49" }
